mapper.update:
update proj_notify set status = 'read', read_time = now(), update_time = now()
where receiver_id = #{receiverId} and status = 'unread' and del_flag = '0'

    and notify_type = #{notifyType}

update proj_notify n set status = 'done', done_time = now(), update_time = now() where n.del_flag = '0' and n.notify_type = 'todo' and n.todo_kind = 'doc' and n.status in ('unread','read')
and n.receiver_id = #{receiverId}
and exists (select 1 from proj_material m where m.project_id = n.project_id and m.del_flag = '0' and COALESCE(m.result_type, '') != '')

update proj_notify n set status = 'done', done_time = now(), update_time = now() where n.del_flag = '0' and n.notify_type = 'todo' and n.todo_kind = 'settle' and n.status in ('unread','read')
and n.receiver_id = #{receiverId}
and exists (select 1 from proj_workload w where w.project_id = n.project_id and w.del_flag = '0' and w.billing_type = 'external' and COALESCE(w.workload, 0) > 0)

update proj_notify n set status = 'done', done_time = now(), update_time = now() where n.del_flag = '0' and n.notify_type = 'todo' and n.todo_kind = 'contract' and n.status in ('unread','read')
and n.receiver_id = #{receiverId}
and exists (select 1 from proj_contract c where c.id = n.biz_id and c.del_flag = '0' and (c.status = 'completed' -- 「存在任意附件」过宽：历史数据导入常自带附件，会导致待办从未出现或立刻消失。 -- 收紧为「已上传签署件」= 合同正本(file_category='contract') 且 签章版(is_final='1')。 or exists (select 1 from proj_contract_attachment a where a.contract_id = c.id and a.del_flag = '0' and a.file_category = 'contract' and a.is_final = '1')))
